package com.empcontrol.agent.command;
import com.empcontrol.agent.config.*; import com.empcontrol.agent.listener.SecurityListener; import com.empcontrol.agent.net.AgentClient; import org.bukkit.command.*; import java.util.*;
public final class EmpControlCommand implements CommandExecutor, TabCompleter { private final AgentClient client; private final SecureStore store; private final SecurityListener security; public EmpControlCommand(AgentClient client, SecureStore store, SecurityListener security){this.client=client;this.store=store;this.security=security;}
  public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args){ if(args.length==0 || args[0].equalsIgnoreCase("status")){ require(sender,"empcontrol.status"); sender.sendMessage("§bEMP Control Agent §7connected="+client.connected()+" queue="+client.queueSize()+" reconnects="+client.reconnects()); return true; } try { switch(args[0].toLowerCase(Locale.ROOT)){ case "link" -> { require(sender,"empcontrol.link"); if(args.length<2){sender.sendMessage("Usage: /empcontrol link <token> [apiBase]"); return true;} String api=args.length>=3?args[2]:System.getenv().getOrDefault("EMP_CONTROL_API_URL","http://localhost:4000"); AgentIdentity id=client.pair(api,args[1]); store.save(id); sender.sendMessage("§aEMP Control linked serverId="+id.serverId()); } case "unlink" -> { require(sender,"empcontrol.link"); store.clear(); sender.sendMessage("§eEMP Control local identity removed. Revoke the agent in the app too."); } case "reload" -> { require(sender,"empcontrol.reload"); store.load().ifPresent(client::connect); sender.sendMessage("§aEMP Control reloaded."); } case "testalert" -> { require(sender,"empcontrol.admin"); client.send("securityEvent", Map.of("type","TEST_ALERT","actor",sender.getName(),"action","test","title","EMP Control test alert")); sender.sendMessage("§aSent test alert."); } case "panic" -> { require(sender,"empcontrol.panic"); boolean on=args.length>1 && args[1].equalsIgnoreCase("on"); security.panic(on, sender); sender.sendMessage("§cPanic mode "+(on?"enabled":"disabled")); } default -> sender.sendMessage("Usage: /empcontrol <status|link|unlink|reload|testalert|panic>"); } } catch(Exception e){ sender.sendMessage("§cEMP Control error: "+e.getMessage()); } return true; }
  private void require(CommandSender sender, String perm){ if(!sender.hasPermission(perm)) throw new SecurityException("Missing permission "+perm); }
  public List<String> onTabComplete(CommandSender s, Command c, String a, String[] args){ return args.length==1?List.of("status","link","unlink","reload","testalert","panic"):List.of(); }
}
